const tagsBySlug = new Map<string, TagInfo>()
for (const tag of TAGS_DATA) {
  tagsBySlug.set(tag.slug, tag)
}

export function getTagData(slug: string): TagInfo | undefined {
  return tagsBySlug.get(slug)
}
